#Requires -Version 7.5
[CmdletBinding(SupportsShouldProcess)]param()
$ErrorActionPreference='Stop';Set-StrictMode -Version 3
if(-not$PSCmdlet.ShouldProcess('Existing sanitized accounting metadata','Crosscheck categories,root/descendant totals andmodel/effort attribution without rescanning native transcripts')){return}
$state=Get-Content /tmp/wordpairs-backup-token-accounting.json -Raw|ConvertFrom-Json -AsHashtable -DateKind String;$directory=$state.directory
$path=Join-Path $directory accounting.json;if((Get-FileHash $path).Hash-cne'66A9BBC8D7760CD4F3E6B2654FBE4F86CAE240447CB6C9E687059BF513092808'){throw 'Accounting drift'}
$a=Get-Content $path -Raw|ConvertFrom-Json -AsHashtable -Depth 100 -DateKind String
$keys=@('input_tokens','cached_input_tokens','cache_write_input_tokens','output_tokens','reasoning_output_tokens','total_tokens','uncached_input_tokens','events')
$checks=@();foreach($collection in @('byModelPeriod','byCentralDay','criticalIntervals','threads')){$sum=@{};foreach($key in $keys){$sum[$key]=[long]0};foreach($row in $a[$collection]){foreach($key in $keys){$sum[$key]+=[long]$row.counts[$key]}};foreach($key in $keys){if($sum[$key]-ne[long]$a.overall[$key]){throw 'Aggregate dimension totals differ'}};$checks+=@{dimension=$collection;allCategoryTotalsExact=$true}}
$root=@($a.threads|Where-Object threadId -CEQ $state.rootThreadId)[0];$descendant=@{};foreach($key in $keys){$descendant[$key]=[long]$a.overall[$key]-[long]$root.counts[$key]}
$first=@{};$previous=@{};$groups=@{};$totalFieldPresent=0;$lastFieldPresent=0;$nativeCacheWritePositive=0;$stop=[DateTimeOffset]::Parse($a.actualStopUtc);$counted=0
$reader=[IO.StreamReader]::new((Join-Path $directory usage-events.jsonl))
try{while($null-ne($line=$reader.ReadLine())){
 $row=$line|ConvertFrom-Json -AsHashtable -Depth 10 -DateKind String;if([DateTimeOffset]::Parse($row.timestamp)-gt$stop){continue}
 if($row.total.ContainsKey('cache_write_input_tokens')){$totalFieldPresent++;if([long]$row.total.cache_write_input_tokens-gt0){$nativeCacheWritePositive++}}
 if($row.last.ContainsKey('cache_write_input_tokens')){$lastFieldPresent++}
 $id=$row.threadId;$vector=($row.total|ConvertTo-Json -Compress);if($previous.ContainsKey($id)-and$previous[$id]-ceq$vector){continue};$previous[$id]=$vector
 $key=$row.provider+'|'+$row.model+'|'+$row.effort
 if(-not$groups.ContainsKey($key)){$groups[$key]=@{provider=$row.provider;model=$row.model;effort=$row.effort;input_tokens=[long]0;cached_input_tokens=[long]0;uncached_input_tokens=[long]0;output_tokens=[long]0;reasoning_output_tokens=[long]0;cache_write_input_tokens=[long]0;total_tokens=[long]0;events=0}}
 $group=$groups[$key];foreach($category in @('input_tokens','cached_input_tokens','output_tokens','reasoning_output_tokens','cache_write_input_tokens','total_tokens')){$group[$category]+=[long]$row.last[$category]};$group.uncached_input_tokens+=([long]$row.last.input_tokens-[long]$row.last.cached_input_tokens);$group.events++;$counted++
 if(-not$first.ContainsKey($id)){$first[$id]=@{timestamp=$row.timestamp;allInitialCounterBaselinesZero=(@($a.threads|Where-Object threadId -CEQ $id)[0].initialInheritedBaseline.total_tokens-eq0)}}
}}finally{$reader.Dispose()}
$groupSum=@{};foreach($key in $keys){$groupSum[$key]=[long]0};foreach($row in $groups.Values){foreach($key in $keys){$groupSum[$key]+=[long]$row[$key]}}
foreach($key in $keys){if($groupSum[$key]-ne[long]$a.overall[$key]){throw 'Independent native-last effort grouping differs'}}
$forkCount=@($a.threads|Where-Object {@($_.forkMetadata|Where-Object {$null-ne$_.forked_from_id}).Count-gt0}).Count
$result=[ordered]@{atLocal=(Get-Date -Format s);accountingPath=$path;accountingSha256=(Get-FileHash $path).Hash;dimensionChecks=$checks;rootThread=$root.threadId;rootCounts=$root.counts;descendantThreads=($a.scopeThreads-1);descendantCounts=$descendant;byNativeModelEffort=@($groups.Values|Sort-Object provider,model,effort);cacheWriteField=@{totalUsageRecordsBeforeStop=$totalFieldPresent;lastUsageRecordsBeforeStop=$lastFieldPresent;positiveReportedCacheWriteRecords=$nativeCacheWritePositive;reportedSum=$a.overall.cache_write_input_tokens;qualification='The native totalandlast usage objects explicitlycontain cache_write_input_tokens in every extractedrecord throughactualstop,andreport0. This is native reportedusage,not a claim about unreportedproviderbilling.'};forkDedup=@{forkedRolloutFiles=$forkCount;initialCounterBaselinesZeroForAllThreads=(@($first.Values|Where-Object {-not$_.allInitialCounterBaselinesZero}).Count-eq0);duplicateCounterEvents=$a.duplicateEventsIgnored;counterResets=$a.counterResetEvents;positiveDeltaVsNativeLastMismatches=$a.deltaVsLastMismatchEvents;uniqueUsageEvents=$counted;method='Forkedfileshave ancestral sessionheaders,but no copied precreationtoken events wereobserved andfirsttotal=firstlast inall10threads. Countfirstlast thenunique cumulativetransitions;native lastsum independentlyexact. Do not adddatabase tokens_used orduplicate inheritedheaders.'};serviceTier=@{observedInSelectedMetadata=$false;billedServiceTier='UNKNOWN';speedOrFastTier='UNKNOWN';longContextBillingTier='UNKNOWN';qualification='Only model/provider/effort were selectedfrom turn_context. Native schema samples showinfo total_token_usage,last_token_usage,model_context_window; no billedserviceTier evidencewasretained. Contextwindow/effort/tooltier are notbillingtier acknowledgements. No furthernative transcript scanperformed.'};separateProviderUsage=@{claude='Root separately accounting;not included';cline='Missing reliable native tokenusage remainsUNKNOWN,notzero;not included';cursor='Not included withoutnative usageproof'};stopExclusion='Actualuserstop2026-11-01T11:31:25.649Z;laterreport/handoff/timerusage excluded.'}
$out=Join-Path $directory verification.json;if(Test-Path $out){throw 'Retain prior verification'};[IO.File]::WriteAllText($out,($result|ConvertTo-Json -Depth 50));[IO.File]::SetUnixFileMode($out,[IO.UnixFileMode]384)
$result|ConvertTo-Json -Depth 50;Get-FileHash $out|Select-Object Path,Hash|ConvertTo-Json
